#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int tc;
    cin >> tc;

    while (tc--) {
        long long n, k, d1, d2;
        cin >> n >> k >> d1 >> d2;

        bool possible = false;

        if (k <= n && n % 3 == 0) {
            using i128 = __int128_t;
            const i128 target = static_cast<i128>(n) / 3;

            for (int s1 : {-1, 1}) {
                for (int s2 : {-1, 1}) {
                    i128 a = static_cast<i128>(s1) * d1;
                    i128 b = 0;
                    i128 c = static_cast<i128>(s2) * d2;

                    i128 minimum = min({a, b, c});
                    a -= minimum;
                    b -= minimum;
                    c -= minimum;

                    i128 baseSum = a + b + c;
                    if (baseSum > k || (static_cast<i128>(k) - baseSum) % 3 != 0)
                        continue;

                    i128 offset = (static_cast<i128>(k) - baseSum) / 3;
                    if (max({a, b, c}) + offset <= target) {
                        possible = true;
                        break;
                    }
                }
                if (possible) break;
            }
        }

        cout << (possible ? "yes\n" : "no\n");
    }

    return 0;
}

