            __int128 target = n / 3;

            for (int s1 : {-1, 1}) {
                for (int s2 : {-1, 1}) {
                    __int128 numerator = (__int128)k - (__int128)s1 * d1
                                         + (__int128)s2 * d2;

                    if (numerator % 3 != 0)
                        continue;

                    __int128 b = numerator / 3;
                    __int128 a = b + (__int128)s1 * d1;
                    __int128 c = b - (__int128)s2 * d2;

                    if (a >= 0 && b >= 0 && c >= 0 &&
                        a <= target && b <= target && c <= target) {
                        possible = true;
                    }
                }
            }
        }

        cout << (possible ? "yes\n" : "no\n");
    }

    return 0;
}

